const initialState = [];

const libraryReducer = (state = initialState, action) => {

    switch(action.type) {
        case "ADD_ALBUM":
            return{
                ...state

            };
        case "REMOVE_ALBUM":
            return{
                ...state
            }
    }
}


export default libraryReducer;
